const message = inputData.customer_message || '';

// Normalize the message for analysis
const normalizedMessage = message.toLowerCase().trim();

// Extract order ID if present (pattern: NS followed by digits)
const orderIdMatch = message.match(/NS\d{4,}/);
const orderId = orderIdMatch ? orderIdMatch[0] : null;

// Classify intent based on keywords
let intent = 'UNKNOWN_UNSUPPORTED';
let clarificationRequired = false;
let escalationRequired = false;
let missingInformation = [];

// Check for ORDER_STATUS keywords
if (/\b(order|status|shipping|delivery|tracking|confirmation|where|when|track)\b/.test(normalizedMessage)) {
  intent = 'ORDER_STATUS';
  // Missing order ID for ORDER_STATUS requests
  if (!orderId) {
    missingInformation = ['order_id'];
  }
}
// Check for RETURNS_REFUNDS keywords
else if (/\b(return|refund|exchange|send back|money back|cancel|wrong item)\b/.test(normalizedMessage)) {
  intent = 'RETURNS_REFUNDS';
}

// Detect ambiguous requests (multiple conflicting intents)
const hasOrderKeywords = /\b(order|status|shipping|tracking)\b/.test(normalizedMessage);
const hasReturnKeywords = /\b(return|refund|exchange)\b/.test(normalizedMessage);
if (hasOrderKeywords && hasReturnKeywords) {
  clarificationRequired = true;
}

// Return the classification result
return {
  intent: intent,
  order_id: orderId,
  missing_information: missingInformation,
  clarification_required: clarificationRequired,
  escalation_required: escalationRequired
};
